import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiStrengthen","description":"","frontmatter":{},"headers":[],"relativePath":"modules/strengthen/index.md","filePath":"modules/strengthen/index.md","lastUpdated":0}`),a={name:`modules/strengthen/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakistrengthen" tabindex="-1">EmakiStrengthen <a class="header-anchor" href="#emakistrengthen" aria-label="Permalink to “EmakiStrengthen”">​</a></h1><p>EmakiStrengthen 是装备强化模块，提供星级强化、锻印 temper、保护材料、里程碑、属性写入、强化层重建和公开 API。它适合制作&quot;装备从 +0 到 +N 逐步成长&quot;的玩法。</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>部分命令仍使用 <code>crack</code> 等历史命名（如 <code>clearcrack</code>），在玩法描述中统一称为&quot;锻印&quot;或&quot;强化痕迹&quot;。</p></div><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>4.8.0</code></td></tr><tr><td>主命令</td><td><code>/emakistrengthen</code></td></tr><tr><td>别名</td><td><code>/estrengthen</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>EmakiItem、EmakiAttribute、PlaceholderAPI</td></tr><tr><td>主要权限</td><td><code>emakistrengthen.use</code>、<code>emakistrengthen.reload</code>、<code>emakistrengthen.debug</code>、<code>emakistrengthen.admin</code></td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>打开强化 GUI、检查主手装备、刷新展示、设置星级与发放材料。</td></tr><tr><td><a href="./recipes.html">强化配方</a></td><td><code>recipes/*.yml</code> 的成功率、材料消耗、失败惩罚、效果与动作。</td></tr><tr><td><a href="./process.html">流程说明</a></td><td>从配方匹配到 PDC 写入与展示刷新的完整强化流程。</td></tr><tr><td><a href="./branch.html">分支树系统</a></td><td>按星级段划分的强化路线，以及不同路线给出的属性、技能与展示。</td></tr><tr><td><a href="./broadcast.html">广播系统</a></td><td>首次达到指定星级时向周围或全服发送通知。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>主手强化层的重建与修改动作。</td></tr><tr><td><a href="./api.html">API 接入</a></td><td>通过 <code>EmakiStrengthenApi</code> 读取状态、预览与执行强化。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>强化流程的 Bukkit 事件与拦截点。</td></tr></tbody></table><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to “核心概念”">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>强化星级</td><td>装备当前强化等级，例如 +1、+2、+10。</td></tr><tr><td>强化配方</td><td>定义哪些装备能强化、需要哪些材料、成功率和结果。</td></tr><tr><td>材料计划</td><td>判断并消耗强化材料、保护材料和锻印材料。</td></tr><tr><td>锻印（temper）</td><td>失败时累积的等级，按 <code>temper_chance_bonus_per_level</code> 提升后续成功率。</td></tr><tr><td>失败降星</td><td>目标星级 ≥ 6 且未使用保护材料时，失败会降 1 星。</td></tr><tr><td>保护材料</td><td><code>protection: true</code> 的材料，失败时阻止降星。</td></tr><tr><td>分支树</td><td>在指定星级后分叉为不同强化路线。</td></tr><tr><td>强化层</td><td>写入装备的 strengthen namespace layer，由 CoreLib 重建展示。</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiStrengthen/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── recipes/</span></span>
<span class="line"><span>│   ├── example_recipe.yml</span></span>
<span class="line"><span>│   └── example_branch_recipe.yml</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   └── strengthen_gui.yml</span></span>
<span class="line"><span>└── lang/</span></span>
<span class="line"><span>    ├── zh_CN.yml</span></span>
<span class="line"><span>    └── en_US.yml</span></span></code></pre></div><p><code>recipes/</code> 决定不同装备的强化规则，<code>gui/strengthen_gui.yml</code> 决定强化界面布局。</p><h2 id="config-yml-主配置" tabindex="-1"><code>config.yml</code> 主配置 <a class="header-anchor" href="#config-yml-主配置" aria-label="Permalink to “config.yml 主配置”">​</a></h2><p><code>success_rates</code> 见<a href="./process.html">流程说明</a>，<code>local_broadcast_radius</code> 与 <code>broadcast.*</code> 见<a href="./broadcast.html">广播系统</a>。其余字段如下：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>version</code></td><td>string</td><td><code>4.8.0</code></td><td>配置结构版本标记；默认资源版本由资源同步流程维护。源码内部另有两个不同用途的常量：该键为空时回退到 <code>4.5.9</code>，完全没有配置文件时 <code>AppConfig.defaults()</code> 用 <code>4.2.9</code>。都不要当作发布版本号。</td></tr><tr><td><code>language</code></td><td>string</td><td><code>zh_CN</code></td><td>使用 <code>lang/&lt;language&gt;.yml</code> 语言文件。</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td><code>true</code></td><td>缺失时是否释放内置默认配方、GUI 与语言资源。</td></tr><tr><td><code>affix.max_level</code></td><td>integer</td><td><code>10</code></td><td>词缀单条上限等级；负值按 <code>0</code> 处理。</td></tr><tr><td><code>affix.capacity_max</code></td><td>integer</td><td><code>100</code></td><td>词缀容量上限；负值按 <code>0</code> 处理。</td></tr><tr><td><code>affix.capacity_cost_per_level</code></td><td>integer</td><td><code>10</code></td><td>每级词缀占用的容量；负值按 <code>0</code> 处理。</td></tr><tr><td><code>affix.bonus_per_level</code></td><td>double</td><td><code>1.0</code></td><td>每级词缀提供的加成量；非有限值按 <code>0</code> 处理。</td></tr><tr><td><code>enhancement.reject_container_target</code></td><td>boolean</td><td><code>false</code></td><td>是否拒绝把容器类物品作为强化目标。</td></tr><tr><td><code>enhancement.reject_container_material</code></td><td>boolean</td><td><code>false</code></td><td>是否拒绝把容器类物品作为强化材料。</td></tr><tr><td><code>enhancement.min_success_rate</code></td><td>double</td><td><code>0.0</code></td><td>成功率下限，用于兜住各类衰减后的结果。</td></tr><tr><td><code>enhancement.diminishing_returns.per_level</code></td><td>double</td><td><code>0.0</code></td><td>达到 <code>start_level</code> 后每级递减的成功率。</td></tr><tr><td><code>enhancement.diminishing_returns.start_level</code></td><td>integer</td><td><code>1</code></td><td>开始应用递减的起始等级。</td></tr><tr><td><code>enhancement.cost_growth.per_level</code></td><td>double</td><td><code>0.0</code></td><td>每级消耗增长系数。</td></tr><tr><td><code>enhancement.cost_growth.max_multiplier</code></td><td>double</td><td><code>0.0</code></td><td>消耗增长的倍率上限。</td></tr><tr><td><code>enhancement.failure_demotion.levels</code></td><td>integer</td><td><code>0</code></td><td>失败时降低的等级数。</td></tr><tr><td><code>enhancement.failure_demotion.floor_level</code></td><td>integer</td><td><code>0</code></td><td>失败降级不会低于该等级。</td></tr><tr><td><code>enhancement.pity_retry.interval_ticks</code></td><td>integer</td><td><code>0</code></td><td>保底计数落盘失败后的重试间隔，单位 tick。</td></tr><tr><td><code>enhancement.pity_retry.max_attempts</code></td><td>integer</td><td><code>0</code></td><td>保底计数落盘的最大重试次数。</td></tr><tr><td><code>enhancement.mastery.exp_per_attempt</code></td><td>double</td><td><code>0.0</code></td><td>每次强化尝试给予的熟练度经验。</td></tr><tr><td><code>enhancement.mastery.exp_per_success</code></td><td>double</td><td><code>0.0</code></td><td>每次强化成功额外给予的熟练度经验。</td></tr><tr><td><code>enhancement.mastery.soft_cap</code></td><td>integer</td><td><code>0</code></td><td>熟练度软上限。</td></tr></tbody></table><h2 id="典型强化流程" tabindex="-1">典型强化流程 <a class="header-anchor" href="#典型强化流程" aria-label="Permalink to “典型强化流程”">​</a></h2><ol><li>玩家用 <code>/estrengthen open</code> 打开强化 GUI。</li><li>放入目标装备、强化材料和可选保护材料。</li><li>模块按配方顶层的 <code>matcher</code> 与 <code>slot_groups</code> 等字段匹配可用强化配方。</li><li>检查条件、材料、经济费用和当前星级上限。</li><li>计算成功率：目标星级基础成功率 + 锻印加成，并钳制到 <code>success_chance_cap</code>。</li><li>触发 <code>StrengthenPreAttemptEvent</code>，允许外部改写成功率或取消。</li><li>执行随机判定并扣除材料与费用。</li><li>成功时星级 +1，写入强化层，执行该星级的 <code>actions.success</code>。</li><li>失败时按规则累积锻印并可能降星，执行 <code>actions.failure</code>。</li><li>CoreLib 重建装备展示；首次达到广播星级时发送本地或全服广播。</li></ol><h2 id="与-attribute-的关系" tabindex="-1">与 Attribute 的关系 <a class="header-anchor" href="#与-attribute-的关系" aria-label="Permalink to “与 Attribute 的关系”">​</a></h2><p>Strengthen 可以仅作为展示和成长系统运行。配置 <code>ea_attribute</code> 效果并安装 EmakiAttribute 后，每个星级可以提供真实属性加成：属性通过 EmakiAttribute 的权威 API 写入结构化 PDC layer，参与真实战斗计算。</p><p>EmakiAttribute 未安装时走 no-op 路径，强化照常完成但不写入属性。</p><h2 id="与-item-的关系" tabindex="-1">与 Item 的关系 <a class="header-anchor" href="#与-item-的关系" aria-label="Permalink to “与 Item 的关系”">​</a></h2><p>安装 EmakiItem 时，Strengthen 会在其条件加载的 integration 包中通过 <code>EmakiItemApi</code> 注册物品层预览提供者，让 EmakiItem 侧能够预览强化层内容。EmakiItem 未安装或被禁用时该注册自动跳过或释放，不影响强化功能。</p>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};